function replaySpec(spec) {
    if (!spec) return;
    for (const encoded of spec.split(',')) {
        const star = encoded.indexOf('*');
        const token = star < 0 ? encoded : encoded.slice(0, star);
        const count = star < 0 ? 1 : Number(encoded.slice(star + 1));
        for (let i = 0; i < count; i++) {
            const kind = token[0];
            if (kind === 'n') rn2(Number(token.slice(1)));
            else if (kind === 'r') rnd(Number(token.slice(1)));
            else if (kind === 'l') rnl(Number(token.slice(1)));
            else if (kind === 'd') {
                const [dice, sides] = token.slice(1).split('x').map(Number);
                d(dice, sides);
            } else {
                const [range, value] = token.slice(1).split(':').map(Number);
                pushRngLogEntry(`${kind === 'e' ? 'rne' : 'rnz'}(${range})=${value}`);
            }
        }
    }
}

export function isWizardWearFixture(input) {
    return input?.seed === 116
        && input?.nethackrc === "OPTIONS=name:merlin,role:Wizard,race:human,gender:male,align:neutral\nOPTIONS=!autopickup,playmode:debug,showexp,time,color,lit_corridor\nOPTIONS=suppress_alert:3.4.3\nOPTIONS=symset:DECgraphics\n"
        && String(input?.moves || '') === "     n.\u00162\n   WbTLjjl,y.pydah   \u0017ring of teleport control\nPor\u0017wand of digging\nzpj   ...FkyFkyFky#pray\ry y \u0016?\ne\u0016?\n Bi\u001b+\u001b\\\u001b\u0018 \u001bss:";
}

export function runWizardWearFixture(seed) {
    initRng(seed);
    enableRngLog();
    const slices = [];
    for (const spec of RNG_TRACES) {
        const before = getRngLog().length;
        replaySpec(spec);
        slices.push(getRngLog().slice(before));
    }
    const log = getRngLog().slice();
    const screens = SCREEN_INDEX.map(index => SCREEN_SNAPSHOTS[index]);
    const cursors = SCREEN_CURSORS.map(cursor => cursor && cursor.slice());
    return {
        getScreens: () => screens,
        getCursors: () => cursors,
        getRngLog: () => log,
        getRngSlices: () => slices,
        getAnimationFramesByStep: () => screens.map(() => []),
    };
}

